<div class="container portal-shell"><div class="portal-topline"><a href="/support">← Help centre</a><span>Enquiry tracking</span></div><section class="portal-header"><div><span class="eyebrow">Your enquiry</span><h1>Track your message.</h1><p>Keep your reference number to return to this page.</p></div></section><?php if ($data['request'] === false): ?><div class="form-error" role="alert">We could not find an enquiry with that reference.</div><a class="text-link" href="/support/contact">Send an enquiry ↗</a><?php else: ?><?php $request = $data['request']; ?><div class="portal-layout"><section class="form-panel enquiry-summary"><span class="request-status"><?= $escape(ucfirst($request['status'])) ?></span><h2><?= $escape($request['subject']) ?></h2><dl><div><dt>Reference</dt><dd><?= $escape($data['reference']) ?></dd></div><div><dt>Submitted</dt><dd><?= $escape(substr((string) $request['created_at'], 0, 16)) ?></dd></div><div><dt>Contact name</dt><dd><?= $escape($request['name']) ?></dd></div><div><dt>Email</dt><dd><?= $escape($request['email']) ?></dd></div><div><dt>Topic</dt><dd><?= $escape(ucfirst($request['category'])) ?></dd></div></dl><h3>Your message</h3><p class="enquiry-message"><?= nl2br($escape($request['message'])) ?></p></section><aside class="portal-aside"><span class="aside-icon" aria-hidden="true">✦</span><h2>What happens next?</h2><p>Our service team will review your enquiry. Keep this reference for your records.</p><a class="text-link" href="/support">Back to help centre ↗</a></aside></div><?php endif; ?></div>
